cd /workspace && node -e "
const mammoth = require('mammoth');
const PDFDocument = require('pdfkit');
const fs = require('fs');

mammoth.extractRawText({path: 'testbed/docs/customer_report.docx'})
  .then(result => {
    const doc = new PDFDocument({margin: 50});
    const output = fs.createWriteStream('testbed/docs/customer_report.pdf');
    doc.pipe(output);

    const lines = result.value.split('\n');
    for (const line of lines) {
      if (line === 'Customer Activity Report') {
        doc.fontSize(18).font('Helvetica-Bold').text(line, {align: 'center'});
        doc.moveDown(1);
      } else if (line && !line.startsWith('  ') && !line.startsWith('Email:') && !line.startsWith('Order ')) {
        // Customer names
        doc.moveDown(0.5);
        doc.fontSize(14).font('Helvetica-Bold').text(line);
      } else if (line.startsWith('Email:')) {
        doc.fontSize(10).font('Helvetica').text(line);
        doc.moveDown(0.3);
      } else if (line.startsWith('Order ')) {
        doc.fontSize(10).font('Helvetica-Bold').text(line);
      } else if (line.trim().startsWith('Items:')) {
        doc.fontSize(10).font('Helvetica').text(line);
        doc.moveDown(0.2);
      } else if (line.trim() === '') {
        // skip empty lines
      } else {
        doc.fontSize(10).font('Helvetica').text(line);
      }
    }

    doc.end();
    output.on('finish', () => {
      const stats = fs.statSync('testbed/docs/customer_report.pdf');
      console.log('PDF created: testbed/docs/customer_report.pdf (' + stats.size + ' bytes)');
    });
  })
  .catch(err => console.error('Error:', err));
"
